","import React from "react";
import { Icon } from "../Icons";

export function FilterSelect({ label, value, options, onChange, active }:
 { label: string; value: string; options: string[]; onChange: (v: string) => void; active: boolean }) {
 const [open, setOpen] = React.useState(false);
 const ref = React.useRef<HTMLDivElement>(null);
 React.useEffect(() => {
 const h = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); };
 document.addEventListener("mousedown", h);
 return () => document.removeEventListener("mousedown", h);
 }, []);
 return (
 <div className={`ci-filter ${active ? "ci-filter--active" : ""}`} ref={ref}
 onClick={() => setOpen(o => !o)} role="button" tabIndex={0}>
 <span className="ci-filter__k">{label}</span>
 <span className="ci-filter__v">{value}</span>
 <Icon.chevronD className="ci-filter__chev" style={{ width: 13, height: 13 }} />
 {open && (
 <div className="ci-filter__menu" onClick={e => e.stopPropagation()}>
 {options.map(o => (
 <div key={o} className={`ci-filter__opt ${o === value ? "ci-filter__opt--sel" : ""}`}
 onClick={() => { onChange(o); setOpen(false); }}>
 {o === value && <Icon.target style={{ width: 12, height: 12 }} />}
 <span style={{ marginLeft: o === value ? 0 : 20 }}>{o}</span>
 </div>
 ))}
 </div>
 )}
 </div>
 );
}
