","/* ============================================================
 Executive Command Center — component styles (PREMIUM LIGHT)
 ============================================================ */

/* ---- Compact executive header ---- */
.cc-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 12px; }
.cc-head__title { font-size: 19px; font-weight: 800; letter-spacing: 0.01em; margin: 0; line-height: 1.1; }
.cc-head__sub { font-size: 11px; color: var(--ci-cyan); letter-spacing: 0.10em; text-transform: uppercase; margin-top: 3px; font-weight: 700; }
.cc-head__meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.cc-pill {
 display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px; border-radius: 999px;
 border: 1px solid var(--ci-border); background: #fff; font-size: 11px; color: var(--ci-text-dim);
}
.cc-pill b { color: var(--ci-text); font-weight: 700; }
.cc-pill--ai { border-color: rgba(10,153,199,0.30); background: var(--ci-cyan-soft); color: var(--ci-cyan); font-weight: 700; }

/* ---- Pipeline connected funnel ---- */
.cc-funnel { position: relative; width: 100%; }
.cc-pipe__legendrow { display: flex; justify-content: space-between; align-items: center; margin-top: 4px; }

/* ---- Cycle readiness ---- */
.cc-cycles { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.cc-cycle { border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); padding: 11px; cursor: pointer; transition: all .16s ease; background: var(--ci-bg-0); }
.cc-cycle:hover { border-color: var(--ci-cyan); transform: translateY(-2px); box-shadow: var(--ci-shadow-soft); }
.cc-cycle__top { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 8px; }
.cc-cycle__yr { font-size: 16px; font-weight: 800; }
.cc-cycle__ov { font-size: 11px; font-weight: 800; }

/* ---- Bullet indicator ---- */
.cc-bullet { margin-bottom: 7px; }
.cc-bullet__row { display: flex; justify-content: space-between; font-size: 10px; color: var(--ci-text-dim); margin-bottom: 3px; }
.cc-bullet__track { height: 6px; border-radius: 4px; background: rgba(18,38,78,0.08); position: relative; overflow: hidden; }
.cc-bullet__fill { height: 100%; border-radius: 4px; }

/* ---- Talent map ---- */
.cc-map-wrap { display: flex; gap: 14px; }
.cc-map { flex: 1.35; min-width: 0; }
.cc-mapbox { width: 100%; height: 320px; border-radius: var(--ci-radius-sm); overflow: hidden; border: 1px solid var(--ci-border); position: relative; background: #dfe7f0; }
.cc-map-toggles { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 8px; }
.cc-snapshot { flex: 1; min-width: 0; border-left: 1px solid var(--ci-border); padding-left: 14px; }
.cc-snap__grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 10px 0; }
.cc-snap__v { font-size: 17px; font-weight: 800; color: var(--ci-text); }
.cc-snap__l { font-size: 10px; color: var(--ci-text-faint); text-transform: uppercase; letter-spacing: 0.05em; }

/* Leaflet popups tuned to the light theme */
.leaflet-container { font-family: var(--ci-font); background: #dfe7f0; }
.leaflet-popup-content-wrapper { border-radius: 10px; box-shadow: var(--ci-shadow); }
.leaflet-popup-content { margin: 10px 12px; font-size: 12px; color: var(--ci-text); }
.leaflet-bar a { color: var(--ci-text); }

/* ---- Velocity quadrant ---- */
.cc-quad-note { display: flex; flex-wrap: wrap; gap: 6px 14px; margin-top: 8px; font-size: 10.5px; color: var(--ci-text-faint); }

/* ---- Opportunity cards ---- */
.cc-opp { border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); padding: 11px; background: var(--ci-bg-0); display: flex; flex-direction: column; gap: 7px; transition: border-color .15s ease; }
.cc-opp:hover { border-color: var(--ci-border-strong); }
.cc-opp__signal { font-size: 12px; font-weight: 700; color: var(--ci-text); line-height: 1.35; }
.cc-opp__why { font-size: 11px; color: var(--ci-text-dim); line-height: 1.35; }

/* ---- Risk queue ---- */
.cc-risk { display: flex; gap: 10px; align-items: flex-start; padding: 9px 10px; border-radius: var(--ci-radius-sm); border: 1px solid var(--ci-border); background: var(--ci-bg-0); cursor: pointer; transition: all .15s ease; }
.cc-risk:hover { border-color: var(--ci-border-strong); background: var(--ci-bg-3); }
.cc-risk__sev { font-size: 9px; font-weight: 800; letter-spacing: 0.05em; padding: 2px 6px; border-radius: 5px; flex: none; margin-top: 1px; }
.cc-sev--CRITICAL { background: var(--ci-red-soft); color: var(--ci-red); }
.cc-sev--HIGH { background: var(--ci-amber-soft); color: var(--ci-amber); }
.cc-sev--MEDIUM { background: rgba(18,38,78,0.07); color: var(--ci-text-dim); }
.cc-risk__body { flex: 1; min-width: 0; }
.cc-risk__subj { font-size: 12px; font-weight: 700; color: var(--ci-text); }
.cc-risk__meta { font-size: 10.5px; color: var(--ci-text-faint); margin-top: 1px; }

/* ---- Action queue with state ---- */
.cc-act { display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: var(--ci-radius-sm); border: 1px solid var(--ci-border); background: var(--ci-bg-0); }
.cc-act__body { flex: 1; min-width: 0; }
.cc-act__title { font-size: 12px; font-weight: 700; color: var(--ci-text); }
.cc-act__meta { font-size: 10.5px; color: var(--ci-text-faint); margin-top: 1px; }
.cc-state { font-size: 9px; font-weight: 800; letter-spacing: 0.05em; padding: 3px 7px; border-radius: 999px; white-space: nowrap; }
.cc-state--NEW { background: rgba(18,38,78,0.07); color: var(--ci-text-dim); }
.cc-state--ASSIGNED { background: var(--ci-cyan-soft); color: var(--ci-cyan); }
.cc-state--INPROGRESS { background: var(--ci-amber-soft); color: var(--ci-amber); }
.cc-state--COMPLETED { background: var(--ci-green-soft); color: var(--ci-green); }

/* ---- AI executive insight strip ---- */
.cc-ai { display: grid; grid-template-columns: repeat(4, 1fr) auto; gap: 14px; align-items: stretch; }
.cc-ai__cell { padding-right: 14px; border-right: 1px solid var(--ci-border); }
.cc-ai__cell:last-of-type { border-right: none; }
.cc-ai__k { font-size: 9.5px; font-weight: 800; letter-spacing: 0.12em; color: var(--ci-cyan); text-transform: uppercase; margin-bottom: 5px; display: flex; align-items: center; gap: 6px; }
.cc-ai__v { font-size: 12px; color: var(--ci-text); line-height: 1.4; }
.cc-ai__actions { display: flex; flex-direction: column; gap: 6px; justify-content: center; }
@media (max-width: 1100px) { .cc-ai { grid-template-columns: 1fr 1fr; } .cc-ai__cell { border-right: none; } }

/* ---- Activity stream ---- */
.cc-feed { display: flex; flex-direction: column; }
.cc-feed__item { display: flex; gap: 10px; align-items: flex-start; padding: 8px 0; border-bottom: 1px solid var(--ci-grid-line); }
.cc-feed__item:last-child { border-bottom: none; }
.cc-feed__ic { width: 26px; height: 26px; border-radius: 8px; flex: none; display: grid; place-items: center; }
.cc-feed__tx { font-size: 11.5px; color: var(--ci-text-dim); line-height: 1.35; flex: 1; }
.cc-feed__tm { font-size: 10px; color: var(--ci-text-faint); white-space: nowrap; }

/* ============================================================
 Pipeline Stage Analysis drawer (overlay)
 ============================================================ */
.ci-drawer--wide { width: 720px; max-width: 94vw; }

.sd-eyebrow { font-size: 9.5px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ci-cyan); margin-bottom: 4px; }
.sd-nav { display: flex; gap: 6px; margin-top: 8px; }
.sd-nav__btn {
 border: 1px solid var(--ci-border); background: #fff; color: var(--ci-text-dim);
 font-family: inherit; font-size: 11px; font-weight: 700; padding: 4px 9px; border-radius: 7px; cursor: pointer; transition: all .14s ease;
}
.sd-nav__btn:hover:not(:disabled) { border-color: var(--ci-cyan); color: var(--ci-cyan); }
.sd-nav__btn:disabled { opacity: 0.4; cursor: not-allowed; }

.sd-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(118px, 1fr)); gap: 9px; }
.sd-kpi { border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); background: var(--ci-bg-0); padding: 10px 11px; }
.sd-kpi__v { font-size: 19px; font-weight: 800; line-height: 1.05; color: var(--ci-text); letter-spacing: -0.01em; }
.sd-kpi__l { font-size: 9.5px; color: var(--ci-text-faint); text-transform: uppercase; letter-spacing: 0.04em; margin-top: 4px; }

.sd-tabs { display: flex; gap: 4px; margin: 16px 0 12px; border-bottom: 1px solid var(--ci-border); }
.sd-tab {
 border: none; background: transparent; color: var(--ci-text-dim); font-family: inherit; font-size: 12.5px; font-weight: 700;
 padding: 8px 12px; cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px; transition: all .14s ease;
}
.sd-tab:hover { color: var(--ci-text); }
.sd-tab--active { color: var(--ci-cyan); border-bottom-color: var(--ci-cyan); }

.sd-section { font-size: 12px; font-weight: 800; color: var(--ci-text); margin: 6px 0 8px; display: flex; align-items: center; gap: 6px; }
.sd-clear { margin-left: auto; border: none; background: transparent; color: var(--ci-cyan); font-size: 11px; font-weight: 700; cursor: pointer; }

.sd-barriers { display: flex; flex-direction: column; gap: 5px; }
.sd-barrier {
 display: grid; grid-template-columns: 1fr auto 42px 54px; align-items: center; gap: 10px;
 padding: 9px 11px; border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm);
 background: var(--ci-bg-0); cursor: pointer; transition: all .14s ease;
}
.sd-barrier:hover { border-color: var(--ci-border-strong); background: var(--ci-bg-3); }
.sd-barrier--sel { border-color: var(--ci-cyan); background: var(--ci-cyan-soft); }
.sd-barrier__label { font-size: 12px; font-weight: 600; color: var(--ci-text); }
.sd-barrier__count { font-size: 13px; font-weight: 800; color: var(--ci-text); text-align: right; }
.sd-barrier__pct { font-size: 11px; text-align: right; }
.sd-barrier__trend { font-size: 11px; font-weight: 700; text-align: right; }

.sd-intervention { margin-top: 14px; border: 1px solid rgba(10,153,199,0.28); border-radius: var(--ci-radius); background: var(--ci-cyan-soft); padding: 14px; }
.sd-intervention__k { font-size: 10px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ci-cyan); display: flex; align-items: center; gap: 6px; margin-bottom: 8px; }
.sd-intervention__txt { font-size: 13px; color: var(--ci-text); line-height: 1.5; margin: 0 0 6px; }
.sd-intervention__sub { font-size: 12px; color: var(--ci-text-dim); line-height: 1.45; margin: 0 0 12px; }
.sd-intervention__actions { display: flex; flex-wrap: wrap; gap: 8px; }
.sd-cohort-done { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 700; color: var(--ci-green); background: var(--ci-green-soft); border-radius: 999px; padding: 4px 10px; margin-bottom: 10px; }

.sd-splits { display: flex; flex-direction: column; gap: 9px; }
.sd-split { padding: 7px 9px; border: 1px solid transparent; border-radius: var(--ci-radius-sm); cursor: pointer; transition: all .14s ease; }
.sd-split:hover { background: var(--ci-bg-3); }
.sd-split--sel { border-color: var(--ci-cyan); background: var(--ci-cyan-soft); }
.sd-split__top { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 5px; flex-wrap: wrap; }
.sd-split__name { font-size: 12.5px; font-weight: 700; color: var(--ci-text); }
.sd-split__nums { font-size: 11px; color: var(--ci-text-dim); display: inline-flex; align-items: center; gap: 4px; flex-wrap: wrap; }
.sd-split__track { position: relative; height: 8px; border-radius: 5px; background: rgba(18,38,78,0.08); overflow: hidden; }
.sd-split__fill { position: absolute; left: 0; top: 0; height: 100%; border-radius: 5px; background: rgba(10,153,199,0.28); }
.sd-split__conv { position: absolute; left: 0; top: 0; height: 100%; border-radius: 5px; background: var(--ci-cyan); }

.sd-filterbar { margin-top: 10px; font-size: 12px; color: var(--ci-text-dim); display: flex; align-items: center; gap: 8px; }
.sd-filterbar button { border: none; background: transparent; color: var(--ci-cyan); font-weight: 700; font-size: 12px; cursor: pointer; }

.sd-src { display: flex; flex-direction: column; }
.sd-src__row { display: grid; grid-template-columns: 1.6fr 1fr 1fr 0.8fr; align-items: center; gap: 8px; padding: 8px 6px; border-bottom: 1px solid var(--ci-grid-line); font-size: 12px; }
.sd-src__row--head { font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--ci-text-faint); font-weight: 700; }
.sd-src__name { font-weight: 600; color: var(--ci-text); }

.sd-attn { display: flex; flex-direction: column; gap: 5px; }
.sd-attn__row { display: flex; align-items: center; gap: 10px; padding: 9px 11px; border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); background: var(--ci-bg-0); cursor: pointer; transition: all .14s ease; }
.sd-attn__row:hover { border-color: var(--ci-border-strong); background: var(--ci-bg-3); }
.sd-attn__main { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1; }
.sd-attn__name { font-size: 12.5px; font-weight: 700; color: var(--ci-text); }
.sd-attn__blk { font-size: 10.5px; max-width: 180px; text-align: right; }

.sd-translist { display: flex; flex-direction: column; gap: 8px; }
.sd-trans { text-align: left; border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); background: var(--ci-bg-0); padding: 11px 12px; cursor: pointer; transition: all .14s ease; font-family: inherit; }
.sd-trans:hover { border-color: var(--ci-cyan); transform: translateY(-1px); box-shadow: var(--ci-shadow-soft); }
.sd-trans--worst { border-color: rgba(217,130,10,0.4); background: var(--ci-amber-soft); }
.sd-trans__head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 6px; }
.sd-trans__label { font-size: 13px; font-weight: 800; color: var(--ci-text); }
.sd-trans__row { display: flex; gap: 14px; flex-wrap: wrap; font-size: 11.5px; margin-bottom: 7px; }

.sd-modal-overlay { position: fixed; inset: 0; z-index: 95; background: rgba(18,38,78,0.4); backdrop-filter: blur(2px); display: grid; place-items: center; animation: ci-fade-in 0.18s ease; padding: 20px; }
.sd-preview, .sd-cohort { background: #fff; border: 1px solid var(--ci-border-strong); border-radius: var(--ci-radius-lg); box-shadow: var(--ci-shadow); width: 440px; max-width: 100%; padding: 18px; animation: ci-fade-in 0.18s ease; }
.sd-preview__head { display: flex; align-items: center; gap: 12px; margin-bottom: 14px; }
.sd-preview__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; margin-bottom: 4px; }

.sd-cohort__head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.sd-cohort__foot { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }
.sd-field { display: flex; flex-direction: column; gap: 4px; margin-bottom: 10px; flex: 1; }
.sd-field > span { font-size: 10px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--ci-text-faint); }
.sd-field input, .sd-field select { font-family: inherit; font-size: 12.5px; color: var(--ci-text); background: var(--ci-bg-0); border: 1px solid var(--ci-border); border-radius: 8px; padding: 8px 10px; outline: none; transition: border-color .15s ease; }
.sd-field input:focus, .sd-field select:focus { border-color: var(--ci-cyan); }
.sd-field input[readonly] { color: var(--ci-text-dim); background: rgba(18,38,78,0.03); }
.sd-field-row { display: flex; gap: 10px; }
","import { createContext, useContext } from 'react'

export type DrawerKind = 'kpi' | 'region' | 'cycle' | 'risk' | 'velo' | 'opp' | 'pipeline' | 'stage'
export interface CmdDrawerState {
 kind: DrawerKind
 data: any
}

export interface CmdCtxValue {
 stage: string | null
 setStage: (k: string | null) => void
 region: string | null
 setRegion: (k: string | null) => void
 sport: string | null
 setSport: (s: string | null) => void
 linkedAction: string | null
 setLinkedAction: (id: string | null) => void
 open: (kind: DrawerKind, data?: any) => void
 toast: (m: string) => void
}

export const CommandContext = createContext<CmdCtxValue>(null as any)
export const useCmd = () => useContext(CommandContext)
","// Executive Command Center — coherent, connected demo data (POV/POC).
// One story: Coastal region = high participation / low conversion; Swimming = deep pipeline;
// Athletics = big discovery but weak conversion; a 17-athlete high-velocity cohort concentrated
// in 3 sports + 2 regions; several elite athletes lack international exposure.

import type { Status } from './demo'

const sp = (seed: number, n = 18) => {
 let s = seed
 const r = () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff
 let v = 42 + r() * 16
 const out: number[] = []
 for (let i = 0; i < n; i++) {
 v = Math.max(8, Math.min(96, v + (r() - 0.42) * 14))
 out.push(v)
 }
 return out
}

