// Derived analysis for a given pipeline transition (index into PIPELINE).
export function stageAnalysis(i: number) {
 const clamped = Math.max(0, Math.min(i, PIPELINE.length - 2))
 const from = PIPELINE[clamped]
 const to = PIPELINE[clamped + 1]
 const meta = STAGE_META[clamped] || { avgDays: 60, target: 50 }
 const population = from.value
 const progressed = to.value
 const rate = Math.round((progressed / population) * 100)
 const notProgressed = population - progressed
 const gap = rate - meta.target
 return { index: clamped, from, to, population, progressed, rate, notProgressed, avgDays: meta.avgDays, target: meta.target, gap }
}

// Approved, non-pejorative wording for the pathway gap (used in pipeline + drawer).
export function pathwayGapText(i: number) {
 const a = stageAnalysis(i)
 return `Priority pathway gap: ${a.from.label} → ${a.to.label} — ${a.rate}% progression; ${a.notProgressed.toLocaleString()} athletes require further review or intervention.`
}
