 {chip("age", "Age 16–21")}
 {chip("top", "Top 10% national")}
 {chip("fast", "Velocity > 75")}
 {chip("notElite", "Not yet elite")}
 </div>
 <div style={{ maxHeight: 260, overflowY: "auto" }}>
 <table className="ci-table tr-table">
 <thead><tr>
 <th>Athlete</th><th>Age</th><th>Sport</th><th>Region</th>
 <th>Local</th><th>Nat'l</th><th>Global gap</th><th>Vel</th><th>Stage</th>
 </tr></thead>
 <tbody>
 {rows.map(a => (
 <tr key={a.id} onClick={() => open("athlete", a)}>
 <td className="ci-table__name">{a.name}</td>
 <td className="ci-num">{a.age}</td>
 <td>{a.sport}</td>
 <td>{a.region}</td>
 <td className="ci-num tr-pct">P{a.localPct}</td>
 <td className="ci-num tr-pct">P{a.nationalPct}</td>
 <td className="ci-num" style={{ color: gapTone(a.globalGap), fontWeight: 700 }}>{a.globalGap}%</td>
 <td className="ci-num" style={{ color: a.velocity >= 80 ? "var(--ci-green)" : "var(--ci-text-dim)" }}>{a.velocity}</td>
 <td><Chip status="ghost">{a.stage}</Chip></td>
 </tr>
 ))}
 {rows.length === 0 && <tr><td colSpan={9} className="ci-faint" style={{ textAlign: "center", padding: 18 }}>No athletes match the current filters.</td></tr>}
 </tbody>
 </table>
 </div>
 </Panel>
 );
}

const NEXT: Record<string, string> = { NEW: "ASSIGNED", ASSIGNED: "IN PROGRESS", "IN PROGRESS": "COMPLETED", COMPLETED: "COMPLETED" };
const stateClass = (s: string) => "cc-state cc-state--" + s.replace(/\s/g, "");

export function ActionQueueRow() {
 const { toast, region } = useRadar();
 const [items, setItems] = React.useState<TalentAction[]>(TALENT_ACTIONS);
 const advance = (id: string) => setItems(it => it.map(a => a.id === id ? (() => { const ns = NEXT[a.state]; toast(`${a.title} → ${ns}`); return { ...a, state: ns }; })() : a));
 return (
 <Panel span={5} hover title="Assessment / Action Queue" sub="Discovery-driven actions · advance to change state">
 <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
 {items.map(a => {
 const rel = region && a.region === region;
 return (
 <div key={a.id} className="cc-act" style={rel ? { borderColor: "var(--ci-cyan)", background: "var(--ci-cyan-soft)" } : undefined}>
 <span className="ci-dot" style={{ background: SC[a.pri], boxShadow: `0 0 6px ${SC[a.pri]}`, flex: "none" }} />
 <div className="cc-act__body">
 <div className="cc-act__title">{a.title}</div>
 <div className="cc-act__meta">{a.cohort} · {a.owner}</div>
 </div>
 <span className={stateClass(a.state)}>{a.state}</span>
 <Button size="sm" variant={rel ? "primary" : "ghost"}
 onClick={() => advance(a.id)}>{a.state === "NEW" ? "Assign" : a.state === "ASSIGNED" ? "Start" : a.state === "IN PROGRESS" ? "Complete" : "Open"}</Button>
 </div>
 );
 })}
 </div>
 </Panel>
 );
}
","import React from "react";
import { Drawer } from "../../Drawer";
import { ActionRow } from "../../Button";
